 29 | static int next_part(char** cursor, char* out, size_t cap) {
 30 |   size_t n = 0;
 31 |   if (!cursor || !*cursor || !**cursor) return 0;
 32 |   while (**cursor && **cursor != '|' && **cursor != '\n' && n + 1 < cap) out[n++] = *((*cursor)++);
 33 |   out[n] = 0;
 34 |   if (**cursor == '|') (*cursor)++;
 35 |   return 1;
 36 | }
