137 | static int draw_executor_stream(AwtsBrowserState* state) {
138 |   const char* stream = AWTS_NATIVE_RENDER_STREAM;
139 |   if (!stream || !*stream) return 0;
140 |   char* copy = _strdup(stream);
141 |   if (!copy) return 0;
142 |   float ox = sx(state, 96), oy = sy(state, 150);
143 |   float scaleX = sw(state, 2), scaleY = -sh(state, 2);
144 |   for (char* line = copy; line && *line;) {
145 |     char* next = strchr(line, '\n');
146 |     if (next) *next++ = 0;
147 |     char kind[16], id[16], a[64], b[64], c[160], d[64], e[64];
148 |     char* at = line;
149 |     memset(kind, 0, sizeof(kind)); memset(id, 0, sizeof(id));
150 |     memset(a, 0, sizeof(a)); memset(b, 0, sizeof(b)); memset(c, 0, sizeof(c));
151 |     memset(d, 0, sizeof(d)); memset(e, 0, sizeof(e));
152 |     next_part(&at, kind, sizeof(kind)); next_part(&at, id, sizeof(id));
153 |     next_part(&at, a, sizeof(a)); next_part(&at, b, sizeof(b));
154 |     next_part(&at, c, sizeof(c)); next_part(&at, d, sizeof(d)); next_part(&at, e, sizeof(e));
155 |     if (!strcmp(kind, "BOX")) {
156 |       float r, g, blue; hex_color(e, &r, &g, &blue);
157 |       rect(ox + atof(a) * scaleX, oy + atof(b) * scaleY, atof(c) * scaleX, atof(d) * scaleY, r, g, blue);
158 |       outline(ox + atof(a) * scaleX, oy + atof(b) * scaleY, atof(c) * scaleX, atof(d) * scaleY, 0.70f, 0.72f, 0.78f);
159 |     } else if (!strcmp(kind, "TEXT")) {
160 |       float r, g, blue; hex_color(d, &r, &g, &blue);
161 |       awts_draw_text(state, ox + atof(a) * scaleX, oy + atof(b) * scaleY, c, r, g, blue);
162 |     } else if (!strcmp(kind, "WEBGL")) {
163 |       rect(sx(state, 470), sy(state, 180 + atoi(id) * 18), sw(state, 220), -sh(state, 10), 0.10f, 0.18f, 0.32f);
164 |     }
165 |     line = next;
166 |   }
167 |   free(copy);
168 |   return 1;
169 | }
